import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Login from './Login'; // Your login page
import Home from './Home';   // Your new dashboard

function App() {
  return (
    <Router>
      <Routes>
        {/* This shows the login page at the base URL */}
        <Route path="/" element={<Login />} />
        
        {/* This shows your Home dashboard at /home */}
        <Route path="/home" element={<Home />} />
      </Routes>
    </Router>
  );
}

export default App;
